public class FunctionPurgeFieldFactory : FieldFactory {
	public static readonly string FIELD_NAME = "Function Purge";
	public static readonly GColor COLOR = new GColor("color.fg.listing.function.purge");

	public FunctionPurgeFieldFactory() : base(FIELD_NAME)
    {
	}

	private FunctionPurgeFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {

	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel newModel, ListingHighlightProvider newHlProvider,
			ToolOptions toolOptions, ToolOptions fieldOptions) {
		return new FunctionPurgeFieldFactory(newModel, newHlProvider, toolOptions, fieldOptions);
	}

	/**
	 * @see ghidra.app.util.viewer.field.FieldFactory#getField(ProxyObj, int)
	 */
	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is Function)) {
			return null;
		}
		Function func = (Function) obj;

		string stringDepth = "UNK";
		int depth = func.getStackPurgeSize();
		switch (depth) {
			case Function.INVALID_STACK_DEPTH_CHANGE:
				stringDepth = "INV";
				break;
			case Function.UNKNOWN_STACK_DEPTH_CHANGE:
				stringDepth = "UNK";
				break;
			default:
				if (depth < 0) {
					stringDepth = "-" + Integer.toHexString(-depth);
				}
				else {
					stringDepth = Integer.toHexString(depth);
				}
		}
		AttributedString @as = new AttributedString(stringDepth, COLOR, getMetrics());
		FieldElement text = new TextFieldElement(@as, 0, 0);
		return ListingTextField.createSingleLineTextField(this, proxy, text, startX + varWidth,
			width, hlProvider);
	}

	/**
	 * @see ghidra.app.util.viewer.field.FieldFactory#getFieldLocation(ghidra.app.util.viewer.field.ListingField, BigInteger, int, ghidra.program.util.ProgramLocation)
